const t0 = Date.now(); const xp0 = sdk.getSkillXp('Magic'); let casts=0; const msgs=[];
const cnt = (re)=>sdk.findInventoryItem(re)?.count||0;
while (Date.now()-t0 < 45000 && cnt(/^air rune$/i) >= 2) {
  const st = sdk.getState();
  const t = st.nearbyNpcs.filter(x=>/^(Man|Woman|Rat|Spider|Mugger|Imp)$/i.test(x.name) && x.optionsWithIndex.some(o=>/attack/i.test(o.text))).sort((a,b)=>a.distance-b.distance)[0];
  if (!t) { await sdk.waitForTicks(4); continue; }
  const tick = st.tick;
  const res = await sdk.sendSpellOnNpc(t.index, 1158);
  await sdk.waitForTicks(5);
  casts++;
  const m = sdk.getState().gameMessages.filter(x=>x.tick>tick).map(x=>x.text);
  if (msgs.length<6) msgs.push([res.success, res.message, ...m]);
}
return { casts, dt: Date.now()-t0, xpGain: sdk.getSkillXp('Magic')-xp0, msgs, air: cnt(/^air rune$/i), pos:[sdk.getState().player.worldX, sdk.getState().player.worldZ] };

const t0 = Date.now(); const xp0 = sdk.getSkillXp('Magic'); let casts=0, hits=0;
const cnt = (re)=>sdk.findInventoryItem(re)?.count||0;
while (Date.now()-t0 < 70000 && cnt(/^air rune$/i) >= 2) {
  const st = sdk.getState();
  const t = st.nearbyNpcs.filter(x=>/^(Man|Woman|Mugger|Rat|Spider)$/i.test(x.name) && x.optionsWithIndex.some(o=>/attack/i.test(o.text))).sort((a,b)=>a.distance-b.distance)[0];
  if (!t) { await sdk.waitForTicks(4); continue; }
  if (t.distance > 4) { await bot.walkTo(t.x, t.z, 1).catch(()=>{}); }
  const r = await bot.castSpellOnNpc(t, 1158, 1500);
  casts++; if (r.xpGained>0) hits++;
  if (/reach/i.test(r.message||'')) { await bot.walkTo(t.x, t.z, 1).catch(()=>{}); }
}
return { casts, hits, xpGain: sdk.getSkillXp('Magic')-xp0, air: cnt(/^air rune$/i) };
